// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(this) && recipient != address(c) && recipient != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 recipientBalanceBefore = address(recipient).balance;
        c.withdrawAll(recipient);
        uint256 recipientBalanceAfter = address(recipient).balance;
        assertTrue(address(c).balance == 0 && recipientBalanceAfter == recipientBalanceBefore + amount);
    }
}
